def declaraciones_desde_inmuebles(apps, schema_editor):
    """Each municipality with a flagged listing gets an open declaration.

    The real start date is unknown, so it is the migration date: staff should correct it in the admin.
    """
    Inmueble = apps.get_model('base', 'Inmueble')
    Declaracion = apps.get_model('base', 'DeclaracionZonaTensionada')
    hoy = datetime.date.today()
    for municipio_id in Inmueble.objects.filter(zona_tensionada=True).values_list('municipio_id', flat=True).distinct():
        Declaracion.objects.get_or_create(municipio_id=municipio_id, desde=hoy)


def inmuebles_desde_declaraciones(apps, schema_editor):
    Inmueble = apps.get_model('base', 'Inmueble')
    Declaracion = apps.get_model('base', 'DeclaracionZonaTensionada')
    hoy = datetime.date.today()
    en_vigor = Declaracion.objects.filter(desde__lte=hoy).exclude(hasta__lt=hoy)
    Inmueble.objects.filter(municipio_id__in=en_vigor.values('municipio_id')).update(zona_tensionada=True)


